// Same-named wires are the state registers.
// Same-named registers are combinational, functional next-state functions.
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [1:0] state, nextstate;
    wire [2:0] g0, g1, g2;
    wire [2:0] r0, r1, r2;
    reg [1:0] state2, nextstate2;
    reg [1:0] state3, nextstate3;
    wire [2:0] g02, g12, g22;
    wire [2:0] r02, r12, r22;
    // State table, combinational next-state function (registerless).
    always @* begin
        case (state)
            2'b00: begin g0 = 1; g1 = 0; g2 = 0; nextstate = (r[0])?2'b01:(r[1])?2'b10:(r[2])?2'b11:2'b00; end
            2'b01: begin g0 = 0; g1 = 1; g2 = 0; nextstate = (r[0])?2'b01:(r[1])?2'b10:(r[2])?2'b11:2'b00; end
            2'b10: begin g0 = 0; g1 = 0; g2 = 1; nextstate = (r[0])?2'b01:(r[1])?2'b10:(r[2])?2'b11:2'b00; end
            2'b11: begin g0 = 0; g1 = 0; g2 = 0; nextstate = (r[0])?2'b01:(r[1])?2'b10:(r[2])?2'b11:2'b00; end
        endcase
    end
    // State registers and combinational next-state function (no registerless
    // part).
    always @(posedge clk) begin
        if (!resetn) state <= 2'b00;
        else state <= nextstate;
    end
    always @* begin
        case (state2)
            2'b00: begin g02 = 1; g12 = 0; g22 = 0; nextstate2 = (r[0])?2'b01:(r[1])?2'b10:(r[2])?2'b11:2'b00; end
