        endcase
    end
    always @(posedge clk) begin
        if (!resetn) state2 <= 2'b00;
        else state2 <= nextstate2;
    end
    always @* begin
        case (state3)
            2'b00: begin g02 = 1; g12 = 0; g22 = 0; nextstate3 = (r[0])?2'b01:(r[1])?2'b10:(r[2])?2'b11:2'b00; end
