module TopModule(
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [1:0] state, next_state;
    wire [2:0] g_comb;
    always @(*) begin
        case (state)
            2'd0: g_comb = 3'b001;
            2'd1: g_comb = 3'b010;
            2'd2: g_comb = 3'b100;
            2'd3: g_comb = 3'b001;
        endcase
    end
    always @(*) begin
        case (state)
            2'd0: next_state = (r[0] | r[1] | r[2]) ? 2'd1 : 2'd0;
            2'd1: next_state = (r[0] & ~r[1] & ~r[2]) ? 2'd2 :
                               (~r[0] & r[1] & ~r[2]) ? 2'd3 : 2'd1;
            2'd2: next_state = (r[1] & ~r[0] & ~r[2]) ? 2'd1 : 2'd0;
            2'd3: next_state = (~r[0] & ~r[1] & r[2]) ? 2'd0 : 2'd3;
            default: next_state = 2'd0;
        endcase
    end
    always @(posedge clk) begin
        if (~resetn) state <= 2'd0;
        else state <= next_state;
    end
    assign g = g_comb;
endmodule

