// One-hot state codes: A=3'b001, B=3'b010, C=3'b011, D=3'b100
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, nextstate;
    wire [2:0] state_onehot;
    reg [2:0] g_reg;
    always @* begin
        case (state)
            3'b001: state_onehot = 3'b001;
            3'b010: state_onehot = 3'b010;
            3'b011: state_onehot = 3'b011;
            3'b100: state_onehot = 3'b100;
        endcase
    end
    always @* begin
        case (state)
            3'b001: nextstate = (r == 3'b001) ? 3'b001 :
                                (r == 3'b010) ? 3'b010 :
                                (r == 3'b011) ? 3'b011 :
                                                3'b100;
            3'b010: nextstate = (r == 3'b010) ? 3'b010 :
                                (r == 3'b001) ? 3'b001 :
                                (r == 3'b011) ? 3'b011 :
                                                3'b100;
            3'b011: nextstate = (r == 3'b011) ? 3'b011 :
                                (r == 3'b010) ? 3'b010 :
                                (r == 3'b001) ? 3'b001 :
                                                3'b100;
            3'b100: nextstate = (r == 3'b100) ? 3'b100 :
                                (r == 3'b001) ? 3'b001 :
                                (r == 3'b010) ? 3'b010 :
                                                3'b011;
        endcase
    end
    always @(posedge clk) begin
        if (~resetn) state <= 3'b001;
        else state <= nextstate;
    end
    always @(*) begin
        case (state)
            3'b001: g_reg = 3'b001;
            3'b010: g_reg = 3'b010;
            3'b011: g_reg = 3'b011;
            3'b100: g_reg = 3'b100;
        endcase
    end
    assign g = g_reg & state_onehot;
endmodule

