// One-hot state codes: state names are the comments on the state diagram
// itself, in alphabetical order.
localparam [2:0] A = 3'b000, B = 3'b001, C = 3'b010, D = 3'b011;

module TopModule(
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, nextstate;
    wire [2:0] priority;
    wire [2:0] grant;
    wire [2:0] requests;
    wire [2:0] t;
    reg [2:0] g_reg;
    always @(*) begin
        case (state)
            A: priority = 3'b110;
            B: priority = 3'b101;
            C: priority = 3'b011;
            D: priority = 3'b111;
        endcase
    end
    always @(*) begin
        requests = r;
        grant = (priority & requests);
    end
    always @(*) begin
        t = state;
        case (state)
            A: if (r[0]) nextstate = B;
               else if (r[1]) nextstate = C;
               else if (r[2]) nextstate = D;
               else nextstate = A;
            B: if (r[0]) nextstate = B;
               else nextstate = A;
            C: if (r[1]) nextstate = C;
               else nextstate = A;
            D: nextstate = A;
        endcase
    end
    always @(*) begin
        case (state)
            A: g_reg = 3'b000;
            B: g_reg = (grant[0]) ? 3'b001 : 3'b000;
            C: g_reg = (grant[1]) ? 3'b010 : 3'b000;
            D: g_reg = 3'b100;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) begin
            state <= A;
        end else begin
            state <= nextstate;
        end
    end
    assign g = g_reg;
endmodule

