// FSM as an arbiter, with explicit state codes (the long hand approach).
module TopModule(input  clk, input  resetn, input [2:0] r, output [2:0] g);
  reg [1:0] state, nextstate;
  reg [2:0] grant;
  always @(*) begin
    case ({r, state}) inside
      {3'b000, 2'd0}: nextstate = 2'd0;
      {3'b001, 2'd0}: nextstate = 2'd1;
      {3'b010, 2'd0}: nextstate = 2'd2;
      {3'b011, 2'd0}: nextstate = 2'd3;
      {3'b001, 2'd1}: nextstate = 2'd1;
      {3'b000, 2'd1}: nextstate = 2'd0;
      {3'b011, 2'd1}: nextstate = 2'd3;
      {3'b010, 2'd1}: nextstate = 2'd2;
      {3'b001, 2'd2}: nextstate = 2'd1;
      {3'b010, 2'd2}: nextstate = 2'd2;
      {3'b011, 2'd2}: nextstate = 2'd3;
      {3'b000, 2'd2}: nextstate = 2'd0;
      {3'b001, 2'd3}: nextstate = 2'd1;
      {3'b010, 2'd3}: nextstate = 2'd2;
      {3'b011, 2'd3}: nextstate = 2'd3;
      default:        nextstate = 2'd0;
    endcase
  end
  always @(*) begin
    case ({r, state}) inside
      {3'b000, 2'd0}: grant = 3'b001;
      {3'b001, 2'd0}: grant = 3'b001;
      {3'b010, 2'd0}: grant = 3'b001;
      {3'b011, 2'd0}: grant = 3'b001;
      {3'b001, 2'd1}: grant = 3'b010;
      {3'b000, 2'd1}: grant = 3'b001;
      {3'b011, 2'd1}: grant = 3'b010;
      {3'b010, 2'd1}: grant = 3'b001;
      {3'b001, 2'd2}: grant = 3'b100;
      {3'b010, 2'd2}: grant = 3'b100;
      {3'b011, 2'd2}: grant = 3'b100;
      {3'b000, 2'd2}: grant = 3'b001;
      {3'b001, 2'd3}: grant = 3'b100;
      {3'b010, 2'd3}: grant = 3'b100;
      {3'b011, 2'd3}: grant = 3'b100;
      default:        grant = 3'b001;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= 2'd0;
    else         state <= nextstate;
  end
  assign g = (state == 2'd0) ? grant : 3'b000;
endmodule

