// The FSM described in the description above, implemented as a Verilog
// module.
module TopModule(
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [1:0] state, next_state;
    reg [2:0] g_reg;
    always @* begin
        case (state)
            2'd0: begin
                if (r[0] | r[1] | r[2]) next_state = 2'd1;
                else next_state = 2'd0;
            end
            2'd1: begin
                if (r[0]) next_state = 2'd2;
                else if (r[1]) next_state = 2'd1;
                else next_state = 2'd0;
            end
            2'd2: begin
                if (r[1]) next_state = 2'd2;
                else if (r[0]) next_state = 2'd1;
                else next_state = 2'd0;
            end
            default: next_state = 2'd0;
        endcase
    end
    always @(*) begin
        case (state)
            2'd0: g_reg = 3'b001;
            2'd1: g_reg = 3'b010;
            2'd2: g_reg = 3'b100;
            default: g_reg = 3'b001;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'd0;
            g <= 3'b001;
        end else begin
            state <= next_state;
            g <= g_reg;
        end
    end
endmodule

