// FSM as an arbiter, with priorities based on the request signals.
module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [1:0] state, next_state;
  wire [2:0] r_onehot;
  wire [2:0] grant;
  // State table
  always @* begin
    case (state)
      2'b00: next_state = (r[0]) ? 2'b01 : ((r[1]) ? 2'b10 : ((r[2]) ? 2'b11 : 2'b00));
      2'b01: next_state = (r[0]) ? 2'b01 : 2'b00;
      2'b10: next_state = (r[1]) ? 2'b10 : 2'b00;
      2'b11: next_state = (r[2]) ? 2'b11 : 2'b00;
      default: next_state = 2'b00;
    endcase
  end
  // One-hot decoder: maps the requests to a 3-bit address (the same as the
  // state). The highest-priority (lowest address) request that is one means
  // the grant goes to that device.
  always @* begin
    case ({r[2], r[1], r[0]})
      3'b000: r_onehot = 3'b000;
      3'b001: r_onehot = 3'b001;
      3'b010: r_onehot = 3'b010;
      3'b011: r_onehot = 3'b000;
      3'b100: r_onehot = 3'b000;
      3'b101: r_onehot = 3'b001;
      3'b110: r_onehot = 3'b010;
      3'b111: r_onehot = 3'b000;
      default: r_onehot = 3'b000;
    endcase
  end
  // Sequential part of the FSM, which sets the outputs based on the state and
  // one-hot decoder output.
  always @(posedge clk) begin
    if (!resetn) begin
      state <= 2'b00;
      g[0] <= 1'b0;
      g[1] <= 1'b0;
      g[2] <= 1'b0;
    end else begin
      state <= next_state;
      g[0] <= (state == 2'b00 && r_onehot == 3'b000) || (state == 2'b01) || (state == 2'b11);
      g[1] <= (state == 2'b01 && r_onehot == 3'b001) || (state == 2'b10) || (state == 2'b11);
      g[2] <= (state == 2'b10 && r_onehot == 3'b010) || (state == 2'b11);
    end
  end
endmodule

