module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    state_t state, next_state;
    always @(*) begin
        case (state)
            A: next_state = (r == 3'b001) ? B :
                            (r == 3'b010) ? C :
                            (r == 3'b000) ? A :
                            (r == 3'b011) ? D : A;
            B: next_state = (r == 3'b010) ? C :
                            (r == 3'b000) ? A :
                            (r == 3'b011) ? D : B;
            C: next_state = (r == 3'b000) ? A :
                            (r == 3'b011) ? D : C;
            D: next_state = (r == 3'b000) ? A :
                            (r == 3'b011) ? D :
                            (r == 3'b001) ? B :
                            (r == 3'b010) ? C : D;
            default: next_state = A;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) state <= A;
        else state <= next_state;
    end
    always @(*) begin
        case (state)
            A: g = 3'b000;
            B: g = 3'b001;
            C: g = 3'b010;
            D: g = 3'b011;
            default: g = 3'b111;
        endcase
    end
endmodule

