// One-hot state codes:
//   A = 3'b001
//   B = 3'b010
//   C = 3'b100
//   D = 3'b101
// The FSM outputs g[i] (the i'th resource grant) as a function of the
// current state and the input r[i].
module TopModule(input  clk, input  resetn, input [2:0] r, output [2:0] g);
  reg [2:0] state, next_state;
  wire [2:0] grant;
  always @(*) begin
    case (state)
      3'b001: grant = 3'b001;
      3'b010: grant = 3'b010;
      3'b100: grant = 3'b100;
      3'b101: grant = 3'b001;
      default: grant = 3'b000;
    endcase
  end
  always @(*) begin
    case (state)
      3'b001: next_state = (r == 3'b001) ? 3'b001 :
                           (r == 3'b010) ? 3'b010 :
                           (r == 3'b100) ? 3'b100 : 3'b101;
      3'b010: next_state = (r == 3'b001) ? 3'b001 : 3'b001;
      3'b100: next_state = (r == 3'b010) ? 3'b010 : 3'b001;
      3'b101: next_state = (r == 3'b100) ? 3'b100 :
                           (r == 3'b001) ? 3'b001 :
                           (r == 3'b010) ? 3'b010 : 3'b101;
      default: next_state = 3'b001;
    endcase
  end
  always @(posedge clk) begin
    if (~resetn) state <= 3'b001;
    else state <= next_state;
  end
  assign g = (state == grant) ? 3'b001 :
             (state == {1'b0, grant[1:0]}) ? 3'b010 :
             (state == {2'b00, grant[2]}) ? 3'b100 : 3'b000;
endmodule

