samples.raw_completion:
// FSM, as an arbiter: grants access to the resource to the first device
// that makes a request, in priority order (r0, r1, r2). The FSM outputs
// g[i] = 1 for a single cycle, as long as the corresponding r[i] is high.
module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [1:0] state, next_state;
  reg [2:0] grant;
  wire [2:0] r_prioritized;
  // Prioritize the requests: grant the request with the highest priority.
  always @* r_prioritized = {r[0], r[1], r[2]};
  // State transition.
  always @* begin
    case (state)
      2'b00: next_state = (r_prioritized == 3'b001) ? 2'b01 :
                           (r_prioritized == 3'b010) ? 2'b10 :
                           (r_prioritized == 3'b100) ? 2'b11 : 2'b00;
      2'b01: next_state = (r_prioritized == 3'b001) ? 2'b01 : 2'b00;
      2'b10: next_state = (r_prioritized == 3'b010) ? 2'b10 : 2'b00;
      2'b11: next_state = (r_prioritized == 3'b100) ? 2'b11 : 2'b00;
    endcase
  end
  // Determine the grant.
  always @* grant = (state == 2'b00) ? r_prioritized[0] :
                    (state == 2'b01) ? r_prioritized[1] : r_prioritized[2];
  // Registers: state and output registers.
  always @(posedge clk) begin
    if (!resetn) state <= 2'b00;
    else state <= next_state;
  end
  always @(posedge clk) begin
    if (!resetn) g <= 3'b000;
    else g <= (state == 2'b00 && grant == 1) ? {1'b1, 2'b00} :
              (state == 2'b01 && grant == 2) ? {1'b0, 2'b01} :
              (state == 2'b10 && grant == 3) ? {1'b0, 2'b10} : 3'b000;
  end
endmodule

