// One-hot state codes: state NAME is encoded as a 3-bit vector (NAME_reg)
// such that the one-hot bit is on the positional location of the state
// number. State numbering is a bit-sequential depth-first search of the
// state transition diagram (as specified in the FSM description).
typedef enum logic [2:0] {
    A_NAME = 3'b000,
    B_NAME = 3'b001,
    C_NAME = 3'b010,
    D_NAME = 3'b011
} state_name;

module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
    state_name state, nextstate;
    reg [2:0] r_reg;
    always @(*) r_reg = r;
    always @(*) begin
        case (state)
            A_NAME: begin
                if (r_reg[0]) nextstate = B_NAME;
                else if (r_reg[1]) nextstate = C_NAME;
                else if (r_reg[2]) nextstate = D_NAME;
                else nextstate = A_NAME;
            end
            B_NAME: begin
                if (r_reg[0]) nextstate = B_NAME;
                else nextstate = A_NAME;
            end
            C_NAME: begin
                if (r_reg[1]) nextstate = C_NAME;
                else nextstate = A_NAME;
            end
            D_NAME: begin
                if (r_reg[0] & r_reg[1] & r_reg[2]) nextstate = D_NAME;
                else nextstate = A_NAME;
            end
            default: nextstate = A_NAME;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) state <= A_NAME;
        else state <= nextstate;
    end
    always @(*) begin
        g[0] = (state == B_NAME);
        g[1] = (state == C_NAME);
        g[2] = (state == D_NAME);
    end
endmodule

