// State codes
localparam A = 3'b000;
localparam B = 3'b001;
localparam C = 3'b010;
localparam D = 3'b011;

// FSM
module TopModule(
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, next_state;
    reg [2:0] g_reg;
    wire [2:0] g_next;
    always @* begin
        case (state)
            A: g_next = (r == 3'b000) ? 3'b000 :
                        (r == 3'b001) ? 3'b001 :
                        (r == 3'b010) ? 3'b010 : 3'b011;
            B: g_next = (r == 3'b001) ? 3'b001 :
                        (r == 3'b000) ? 3'b000 :
                        (r == 3'b010) ? 3'b010 : 3'b011;
            C: g_next = (r == 3'b010) ? 3'b010 :
                        (r == 3'b001) ? 3'b001 :
                        (r == 3'b000) ? 3'b000 : 3'b011;
            D: g_next = (r == 3'b000) ? 3'b000 :
                        (r == 3'b001) ? 3'b001 :
                        (r == 3'b010) ? 3'b010 : 3'b011;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) begin
            state <= A;
            g_reg <= 3'b000;
        end else begin
            state <= next_state;
            g_reg <= g_next;
        end
    end
    assign g = g_reg;
    always @* begin
        case (state)
            A: next_state = (r == 3'b000) ? A :
                            (r == 3'b001) ? B :
                            (r == 3'b010) ? C : D;
            B: next_state = (r == 3'b001) ? B :
                            (r == 3'b000) ? A :
                            (r == 3'b010) ? C : D;
            C: next_state = (r == 3'b010) ? C :
                            (r == 3'b001) ? B :
                            (r == 3'b000) ? A : D;
            D: next_state = (r == 3'b000) ? A :
                            (r == 3'b001) ? B :
                            (r == 3'b010) ? C : D;
        endcase
    end
endmodule

