// One-hot state codes:
//   A = 3'b001
//   B = 3'b010
//   C = 3'b100
//   D = 3'b000
// State transition diagram is:
//   A        --r0=0,r1=0,r2=0--> A
//   A        -------r0=1-------> B
//   A        -----r0=0,r1=1----> C
//   A        --r0=0,r1=0,r2=0--> D
//   B (g0=1) -------r0=1-------> B
//   B (g0=1) -------r0=0-------> A
//   C (g1=1) -------r1=1-------> C
//   C (g1=1) -------r1=0-------> A
//   D (g2=1) --r0=0,r1=0,r2=1--> E
//   E        --r0=1,r1=0,r2=0--> F
//   F (g2=1) --r0=0,r1=0,r2=0--> F
//   F (g2=1) ----r0=1,r1=0,r2=0--> D
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, next_state;
    reg [2:0] state_reg;
    always @(*) begin
        case (state)
            3'b001: next_state = (r == 3'b001) ? 3'b001 :
                                 (r == 3'b010) ? 3'b010 :
                                 (r == 3'b100) ? 3'b100 : 3'b000;
            3'b010: next_state = (r == 3'b001) ? 3'b010 : 3'b001;
            3'b100: next_state = (r == 3'b010) ? 3'b100 : 3'b001;
            3'b000: next_state = (r == 3'b100) ? 3'b000 :
                                 (r == 3'b001) ? 3'b011 : 3'b001;
            3'b011: next_state = (r == 3'b100) ? 3'b001 :
                                 (r == 3'b001) ? 3'b001 :
                                 (r == 3'b010) ? 3'b010 : 3'b000;
            default: next_state = 3'b000;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) state_reg <= 3'b001;
        else state_reg <= next_state;
    end
    assign g = (state_reg == 3'b001) ? 3'b001 :
               (state_reg == 3'b010) ? 3'b010 :
               (state_reg == 3'b100) ? 3'b100 : 3'b000;
    always @(posedge clk) state <= state_reg;
endmodule

